(function(){
'use strict';
const G=window.GuildGame, KEY='contract-operations-playtest-031-v1';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const credits=n=>Number(n).toLocaleString('en-US');
const workReady=m=>G.available(m)&&(m.employment!=='retained'||m.retainerPaidTurn===state.turn);
let state,storage=true,tab='development',activeOfficer='command',modalType=null,dialogData=null;
try{const raw=localStorage.getItem(KEY);const v=raw&&JSON.parse(raw);state=v&&v.schema==='contract-operations-browser-1'&&['0.3.1','0.3.2','0.3.3','0.3.4','0.3.5','0.3.6','0.3.7','0.3.8','0.3.9','0.3.10'].includes(v.rules)&&Array.isArray(v.mercs)&&Array.isArray(v.board)?G.migrate(v):G.fresh();}catch{state=G.fresh();storage=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storage=false;}if($('save-status'))$('save-status').textContent=storage?'Progress is saved in this browser. Export notes to share here.':'Browser saving is unavailable. Export notes before closing.';}
function notify(t,bad=false){$('notice').className='notice shown'+(bad?' error':'');$('notice').textContent=t;}
function run(fn){try{fn();save();render();return true;}catch(e){notify(e.message,true);const node=$('modal-error');if(node)node.textContent=e.message;return false;}}
function statusName(m){if(m.status==='Available'&&m.employment==='retained'&&m.retainerPaidTurn!==state.turn)return 'Retainer unfunded';if(m.status==='Onboarding')return 'Onboarding · T'+m.readyAt;if(m.status==='Recovering')return 'Recovering · until T'+m.readyAt;if(m.status==='Training'){let c=state.cohorts.find(c=>c.active&&c.ids.includes(m.id));return 'Training · block '+(c?.block||1);}return m.status;}
function isActionDisabled(){return state.phase!=='activity'||state.actions<1;}
function button(label,action,extra='',disabled=false,css='primary'){return `<button class="${css}" data-do="${action}" ${extra} ${disabled?'disabled':''}>${label}</button>`;}
function badge(kind,text){return `<span class="badge ${esc(kind)}">${esc(text)}</span>`;}
function render(){
 $('turn-number').textContent=String(state.turn).padStart(2,'0');$('phase-caption').textContent={activity:'Activity · Plan this interval',upkeep:'Upkeep · Personnel and bills',event:'Events · Contracts and monthly event',advancement:'Advancement · Close the turn'}[state.phase];
 const crew=G.localMercs(state).filter(m=>!['Candidate','Expired'].includes(m.status));const avail=crew.filter(workReady).length;const arrears=state.arrears.reduce((a,b)=>a+b.amount,0);const nextBill=G.forecast(state);const repTier=G.V.reputation_tiers.find(t=>state.reputation>=t[1]&&state.reputation<=t[2])[0];
 $('stats').innerHTML=`<div class="stat"><p class="eyebrow">TREASURY</p><div class="stat-value">${credits(state.cash)}<small>credits</small></div><div class="stat-bottom ${arrears?'bad':''}">${arrears?credits(arrears)+' owed in arrears':'Known next Upkeep: '+credits(nextBill)+' · wages separate'}</div></div><div class="stat"><p class="eyebrow">GUILD DEVELOPMENT</p><div class="stat-value">Level ${state.guildLevel}</div><div class="stat-bottom">${state.guildXP}/1,000 XP${state.pendingGuildXP?' · +'+state.pendingGuildXP+' pending':''}</div><div class="bar"><i style="width:${Math.min(100,(state.guildXP+state.pendingGuildXP)/10)}%"></i></div></div><div class="stat"><p class="eyebrow">REPUTATION</p><div class="stat-value">${state.reputation>=0?'+':''}${state.reputation}<small>${esc(repTier)}</small></div><div class="stat-bottom">Failure hurts public trust. Paying crew affects Loyalty.</div></div><div class="stat"><p class="eyebrow">PERSONNEL</p><div class="stat-value">${avail}<small>available / ${crew.length} local roster</small></div><div class="stat-bottom">${state.metrics.completed} completed · ${state.metrics.failed} failed</div></div>`;
 const phaseIndex={upkeep:0,activity:3,event:4,advancement:5}[state.phase];$('timeline').innerHTML=['01 Upkeep','02 Budget','03 Commerce','04 Activity','05 Events','06 Advancement'].map((x,i)=>`<span class="${i===phaseIndex?'current':i<phaseIndex?'done':''}">${x}</span>`).join('');
 $('activity-controls').classList.toggle('hidden',state.phase!=='activity');$('active-officer').innerHTML=state.officers.map(o=>`<option value="${o.id}" ${o.id===activeOfficer?'selected':''}>${esc(o.name)} · ${esc(o.role)}</option>`).join('');$('officer-note').textContent='Operating at '+G.operating(state).name+'. Use the shared action pool. PC administration uses an advancing demo benchmark; actual rolls show the modifier.';$('pay-arrears').classList.toggle('hidden',!arrears);
 $('capacity').innerHTML=`<div class="action-number">${state.actions}<span>of ${G.actionPool(state)} actions</span></div><div class="action-pips">${Array.from({length:G.actionPool(state)},(_,i)=>`<i class="${i>=state.actions?'spent':''}"></i>`).join('')}</div>${state.officers.map(o=>`<div class="officer-line"><b>${esc(o.name)}</b><span>${o.used} action${o.used===1?'':'s'} led${o.baseId?'':' · '+o.heroPoints+' Hero Point'+(o.heroPoints===1?'':'s')}</span></div>`).join('')}<p class="table-note" style="color:#b6c8bd">${state.partySize} PCs + ${state.guildLevel-1} Guild Level bonus. Each player chooses one action or contributes it to a joint 2/3-action activity first; allocate remaining actions together. No personal action cap.</p>`;
 $('crew-glance').innerHTML=crew.slice(0,10).map(m=>`<div class="crew-line"><span class="avatar ${esc(m.color)}">${esc(m.name.slice(0,2).toUpperCase())}</span><div><b>${esc(m.name)}</b><small>Level ${m.level} · Loyalty ${m.loyalty}</small></div><span class="crew-status">${esc(statusName(m))}</span></div>`).join('');
 if($('feedback').value!==state.feedback)$('feedback').value=state.feedback||'';
 $('board-count').textContent=state.board.filter(c=>c.baseId===state.operatingBase&&['Offer','Accepted'].includes(c.status)).length;
 document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));
 renderStage();renderRolls();renderWorkspace();save();
}
function renderStage(){if(state.phase==='upkeep'){renderUpkeep();return;}let html='';if(state.phase==='upkeep'||(state.phase==='event'&&!state.operations?.complete)){const operations=state.phase==='event';const settlement=operations?state.operations:state.upkeep;const j=operations?(state.operations.pendingReview?state.jobs.find(j=>j.id===state.operations.pendingReview.job):G.nextJob(state)):null;if(j){html=`<section class="stage-card"><p class="eyebrow">EVENTS / CONTRACT RESOLUTION</p><h2>${esc(j.contract.name)}</h2><p>Your leads were locked at departure. Roll each phase once; the crew’s relevant supporters contribute automatically. All due client receipts arrive before successful contractor wages.</p><div class="roll-grid">${j.quote.checks.map((c,p)=>{const r=j.rolls[p];return `<div class="phase-result ${p===j.rolls.length?'active':''}"><span>${p+1} · ${esc(c.phase)}</span>${r?`<strong class="${r.degree<2?'roll-fail':''}">${esc(G.names[r.degree])}</strong><small>d20 ${r.face} ${r.actualModifier>=0?'+':''}${r.actualModifier} =${r.face+r.actualModifier} / DC${r.dc}</small>${rerollNote(r)}${r.complication?'<p class="phase-complication">'+esc(r.complication.text)+'</p>':''}`:`<strong>—</strong><small>${esc(c.leadName)} · ${esc(c.skill)} +${c.modifier} / DC${c.dc}</small>`}</div>`;}).join('')}</div>${state.operations.pendingReview?heroRerollControls(j):''}${state.operations.pendingReview?(j.rolls.length===3?button('Review complete · continue →','review-phase'):button('Roll '+G.phases[j.rolls.length]+' · d20 →','roll-next')):button('Roll '+G.phases[j.rolls.length]+' · d20','roll')}<p class="table-note">${esc(G.completionRule(j.contract,j.quote.contractRules||j.rulesSnapshot||G.contractRule(j.contract)))} Critical Success counts once. No fourth check.</p></section>`;}else{html=`<section class="stage-card"><p class="eyebrow">${operations?'EVENTS / CONTRACT RESULTS':'UPKEEP / PERSONNEL & BILLS'}</p><h2>${operations?'This turn’s contracts are settled.':'Personnel and routine bills are settled.'}</h2><p>${operations?'Choose failed-job pay and MVP, then resolve the monthly event. Activity is finished for this turn.':'Training and scheduled availability update here. Rent and facility bills use the treasury remaining after prior Events settlement.'}</p>${operations?state.jobs.filter(j=>j.settled&&j.due===state.turn).map(missionResults).join(''):''}${settlement.choices.map(c=>upkeepChoice(c)).join('')}${!settlement.choices.length?`<div class="button-row">${button(operations?'Continue to monthly event →':'Open this turn’s Activity →',operations?'finish-operations':'finish-upkeep')}</div>`:''}</section>`;}}
 else if(state.phase==='event'&&state.operations?.complete){const e=state.event;html=`<section class="stage-card"><p class="eyebrow">EVENTS / ONE VISIBLE MONTHLY EVENT</p><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="button-row">${button(e.type==='lead'?'Keep the lead':e.type==='community'?'Accept the introduction':'Acknowledge the concern','event-accept')}${e.type!=='concern'?button('Let it pass','event-pass','',false,'quiet'):''}</div><p class="table-note">Immediate choices are free. Substantial follow-up uses next turn’s actions.</p></section>`;}
 else if(state.phase==='advancement'){html=`<section class="stage-card"><p class="eyebrow">ADVANCEMENT / GUILD TURN ${state.turn} COMPLETE</p><h2>${state.turn>=6?'Your guild is taking shape.':'Close the books. Plan the next month.'}</h2><p>Guild Level ${state.guildLevel} · ${state.guildXP}/1,000 XP. ${state.featChoices?'You have '+state.featChoices+' Guild Feat choice'+(state.featChoices>1?'s':'')+' available. You may choose now or save them.':'Organizational XP has settled. New capacity applies next boundary.'}</p>${state.featChoices?`<div class="feat-grid">${G.availableGuildFeats(state).map(f=>`<div class="feat-choice"><h3>${esc(f.name)}</h3><p>${esc(f.text)}</p>${button('Choose feat','guild-feat',`data-id="${f.id}"`,false,'secondary')}</div>`).join('')}</div>`:''}<div class="button-row">${button('Advance 30 days · Turn '+(state.turn+1)+' →','advance')}${state.turn>=6?button('Copy first-season notes','export','',false,'quiet'):''}</div><p class="table-note">Available offers and recruits last only through their printed expiry. No newly started work resolves at this boundary.</p></section>`;}
 $('stage-panel').innerHTML=html;
}

function missionResults(j){return `<article class="mission-summary"><h3>${esc(j.contract.name)} · ${j.result?.success?'Completed':'Failed'}</h3><p><b>${esc(j.result?.completionReason||G.missionOutcome(j).completionReason)}</b></p><div class="roll-grid">${j.rolls.map((r,p)=>`<div class="phase-result"><span>${esc(G.phases[p])} · ${esc(r.leadName)}</span><strong class="${r.degree<2?'roll-fail':''}">${esc(G.names[r.degree])}</strong><small>d20 ${r.face} ${r.actualModifier>=0?'+':''}${r.actualModifier} =${r.face+r.actualModifier} / DC${r.dc}</small>${rerollNote(r)}${r.complication?'<p class="phase-complication">'+esc(r.complication.text)+'</p>':''}</div>`).join('')}</div>${j.result?.complications?.map(c=>'<p class="bad-text">'+esc(c.text)+'</p>').join('')||''}<p><b>Guild XP: ${j.result?.success?(j.result.guildXP??j.quote.guildAward?.xp??j.quote.contractRules?.guild_xp??0):0}</b>${j.quote.guildAward?' · '+j.quote.guildAward.label+' for Guild Level '+j.quote.guildAward.guildLevel+' at departure':' · previous deployed quote'}</p>${j.result?.exceptionalGuidance?'<p class="good-text">'+esc(j.result.exceptionalGuidance)+'</p>':''}${j.result?.additionalReward?'<p class="good-text">'+esc(j.result.additionalReward)+'</p>':''}</article>`;}
function renderRolls(){const node=$('roll-results');if(!node)return;const rolls=state.rollHistory||[],r=rolls[rolls.length-1];node.innerHTML=r?`<section class="admin-result" aria-live="polite"><div><p class="eyebrow">GUILD CHECK · TURN${r.turn??state.turn}</p><h3>${esc(r.label)} · ${esc(G.names[r.degree])}</h3><p>${esc(r.officer||'Officer')}: <b>d20 ${r.face} ${r.modifier>=0?'+':''}${r.modifier} =${r.face+r.modifier}</b> versus <b>DC${r.dc}</b>.</p></div><details><summary>Recent guild rolls</summary><table class="invoice-table"><thead><tr><th>Action</th><th>Roll / DC</th><th>Result</th></tr></thead><tbody>${rolls.slice(-8).reverse().map(x=>`<tr><td>T${x.turn??'?'} ·${esc(x.label)}</td><td>d20 ${x.face} ${x.modifier>=0?'+':''}${x.modifier} =${x.face+x.modifier} /${x.dc}</td><td>${esc(G.names[x.degree])}</td></tr>`).join('')}</tbody></table></details></section>`:'';node.innerHTML+=discoveryPanel();}

function upkeepChoice(c){if(c.type==='failedPay'){const j=state.jobs.find(j=>j.id===c.job);return `<div class="choice-box"><h3>${esc(j.contract.name)} · contractor pay</h3><p><b>${esc(j.result?.completionReason||G.missionOutcome(j).completionReason)}</b></p><p>No client payout. Choose actual funded wages; the waived remainder is not default debt. This does not offset Reputation loss.</p><div class="button-row">${button('Full · '+credits(j.quote.pay)+' · Loyalty +5','upkeep-choice',`data-id="${c.id}" data-value="full"`,state.cash<j.quote.pay,'secondary')}${button('Half · '+credits(G.round(j.quote.pay*.5))+' · Loyalty unchanged','upkeep-choice',`data-id="${c.id}" data-value="half"`,state.cash<G.round(j.quote.pay*.5),'secondary')}${button('None · Loyalty −5','upkeep-choice',`data-id="${c.id}" data-value="none"`,false,'quiet')}</div></div>`;}if(c.type==='mvp'){const j=state.jobs.find(j=>j.id===c.job);return `<div class="choice-box"><h3>${esc(j.contract.name)} · name one MVP</h3><p>Choose a lead or supporter with a recorded material contribution. Completion grants equal base XP; MVP adds 50 to one operative.</p><div class="button-row">${c.eligible.map(i=>button(esc(G.merc(state,i).name),'upkeep-choice',`data-id="${c.id}" data-value="${i}"`,false,'secondary')).join('')}${button('No MVP','upkeep-choice',`data-id="${c.id}" data-value="none"`,false,'quiet')}</div></div>`;}const t=state.cohorts.find(t=>t.id===c.cohort);let cost=null,reason='';try{cost=G.trainingCost(state,t.ids,t.facilityId||'offsite');}catch(e){reason=e.message;}const next=G.round(150*(1+Math.min(.1*t.block,.5)));return `<div class="choice-box"><h3>Training cohort · continue or release</h3><p>${t.ids.map(i=>esc(G.merc(state,i).name)).join(', ')}. Next block: ${next} XP each, ${cost===null?'unavailable':cost+' credits'}; no new Guild Action. Releasing makes them Available and ends the streak.</p><div class="button-row">${reason?'<p class="bad-text">'+esc(reason)+'</p>':''}${button('Continue · '+(cost??'—')+' credits','upkeep-choice',`data-id="${c.id}" data-value="continue"`,cost===null||state.cash<cost||!state.upkeep?.settled,'secondary')}${button('Release the cohort','upkeep-choice',`data-id="${c.id}" data-value="stop"`,false,'quiet')}</div></div>`;}
function renderWorkspace(){if(tab==='contracts')renderContracts();else if(tab==='people')renderPeople();else if(tab==='development')renderDevelopment();else renderLog();}
function renderContracts(){const active=state.board.filter(c=>c.baseId===state.operatingBase&&['Offer','Accepted'].includes(c.status));const accepted=active.filter(c=>c.status==='Accepted'),offers=active.filter(c=>c.status==='Offer');let html=`<div class="section-heading"><h2>The contract board</h2><span class="small-label">${state.freeAcquisition?'FREE ACQUISITION / A/B':'ONE-ACTION ACQUISITION'}</span></div>`;if(accepted.length)html+=`<section class="subsection"><div class="subsection-head"><h3>Accepted · awaiting crew</h3><p>Deployment is routine.</p></div><div class="contracts">${accepted.map(contractCard).join('')}</div></section>`;html+=`<section class="subsection"><div class="contracts">${offers.length?offers.map(contractCard).join(''):`<div class="empty"><h3>No available offers.</h3><p>Work the Network for leads, or wait for an event/contact. The board does not refill automatically.</p>${button('Search for contract leads','network-contracts','',isActionDisabled(),'secondary')}</div>`}</div></section>`;const underway=state.jobs.filter(j=>!j.settled);if(underway.length)html+=`<section class="subsection"><h3>Operating this interval</h3>${underway.map(j=>`<div class="panel"><span class="badge deployed">DEPLOYED</span><h3>${esc(j.contract.name)}</h3><p class="table-note">Resolves in Events · Turn ${j.due} · ${j.ids.map(i=>esc(G.merc(state,i).name)).join(', ')} · frozen wages ${j.quote.pay} · successful client payout ${j.quote.payout}</p></div>`).join('')}</section>`;html+=`<section class="subsection"><div class="action-grid"><div class="action-card"><h3>Work the Network</h3><p>Diplomacy normally generates three leads; Critical Failure yields zero or one. Degree determines random level, difficulty and rarity. Securing a lead is a separate decision.</p><div class="price">1 action <span>· no cash cost</span></div>${button('Find leads','network-contracts','',isActionDisabled(),'secondary')}</div><div class="action-card"><h3>Broker Exclusive Deal</h3><p>Trained Diplomacy and Friendly Reputation. Seek a harder, richer, deadline-bound offer. Never accept without ready personnel.</p><div class="price">1 action · 50 credits</div>${button('Pursue an exclusive','broker','',isActionDisabled()||state.reputation<20||!G.officer(state,activeOfficer).skills.Diplomacy||state.cash<50,'secondary')}</div></div></section>`;$('workspace').innerHTML=html;}
function contractCard(c){let threat=G.contractThreat(state,c),card=G.contractRule(c),payout=G.contractPayout(c.level,card.payout_factor);let accepted=c.status==='Accepted';let waiver=c.kind==='standard'&&state.contacts.includes(c.client)&&!state.trustedUsed&&(state.guildFeats.includes('trusted')||state.guildFeats.includes('standing'));let free=G.acquisitionCost(state,c,false).cost===0;let canSecure=state.phase==='activity'&&(free||!isActionDisabled()||waiver);return `<article class="contract ${accepted?'accepted':''}"><div class="contract-header">${badge(accepted?'accepted':c.kind,(accepted?'Accepted · ':'')+threat.label+(c.kind==='exclusive'?' · Exclusive':''))}<span class="level">LEVEL ${c.level}</span></div><h3>${esc(c.name)}</h3><p class="contract-risk"><b>${threat.xp} Guild XP</b> on completion · ${threat.label} for Guild Level ${state.guildLevel}</p><div class="client">${esc(c.client)} · ${esc(c.rarity||'Common')}</div><p style="margin-top:12px">${esc(c.description)}</p><p class="contract-risk"><b>Completion: ${esc(G.completionRule(c))}</b></p><div class="terms"><div><strong>${credits(payout)}</strong><small>credits on success · recommended crew</small></div><div style="text-align:right"><b>${card.required_successes} of 3</b><small>successful phases</small></div></div><p class="contract-risk">${esc(G.consequencePreview(c))}</p><div class="card-buttons">${accepted?button('Assign & deploy','deploy',`data-id="${c.id}"`,state.phase!=='activity') :button(free?'Secure · free':waiver?'Secure · waiver available':'Secure · 1 action','secure',`data-id="${c.id}"`,!canSecure)}${button('Card details','details',`data-id="${c.id}"`,false,'quiet')}</div>${accepted?button('Operations Briefing · 2 actions','briefing',`data-id="${c.id}"`,state.phase!=='activity'||state.guildLevel<3||state.actions<2||!officerOffice('field')||!!c.preparation,'text-button'):''}${accepted?button('Extraction Contingency · 3 actions','contingency',`data-id="${c.id}"`,state.phase!=='activity'||state.guildLevel<4||state.actions<3||!officerOffice('field')||!!c.contingency||state.contingencyTurn===state.turn,'text-button'):''}${accepted?button('Digital Recon · 1 action','recon',`data-id="${c.id}"`,isActionDisabled()||!G.officer(state,activeOfficer).skills.Computers||!!c.preparation,'text-button'):''}<p class="risk-line">${accepted?'Deploy by Turn '+c.deployBy:'Offer through end of Turn '+c.expires} · crew 3 / 4 / 6 · min Squad Level ${Math.max(1,c.level-2)} · DC${G.V.level_dc[c.level]+card.dc_offset} (${card.dc_offset>=0?'+':''}${card.dc_offset} difficulty)${card.mandatory_recovery?' · recovery '+card.mandatory_recovery+' turn':''}</p></article>`;}
function renderPeople(){const crew=G.localMercs(state).filter(m=>!['Candidate','Expired'].includes(m.status));const candidates=G.localMercs(state).filter(m=>m.status==='Candidate'&&m.expires>=state.turn);let html=`<div class="section-heading"><h2>Personnel · ${esc(G.operating(state).name)}</h2><span class="small-label">EXPLICIT SKILLS / MONTHLY COMMITMENTS</span></div><div class="people-grid">${crew.map(personCard).join('')}</div><section class="subsection"><div class="subsection-head"><h3>Recruitment candidates</h3><p>Hiring costs an action. New hires start next turn.</p></div>${candidates.length?`<div class="people-grid">${candidates.map(personCard).join('')}</div>`:`<div class="empty"><p>No active candidates. A network search finds options; hiring each operative is separate.</p>${button('Find candidates','network-recruits','',isActionDisabled(),'secondary')}</div>`}</section><section class="subsection"><div class="action-grid"><div class="action-card"><h3>Run Training Drills</h3><p>Commit up to ${G.trainingCapacity(state)} Available operatives for 30 days. First block150 XP; consecutive bonuses cap at50%.</p><div class="price">1 action <span>·25/person; funded suite supplies trainer</span></div>${button('Select a training cohort','train','',isActionDisabled()||!crew.some(workReady),'secondary')}</div><div class="action-card"><h3>Boost Morale</h3><p>Invest in Available or returned Recovering crew. Loyalty helps keep people committed; it does not erase failed-contract Reputation.</p><div class="price">1 action · 10 per person</div>${button('Recognize the crew','morale','',isActionDisabled(),'secondary')}</div><div class="action-card"><h3>Establish Recovery Protocol</h3><p>Trained Medicine. Treat returned Recovering staff now. Successful care can release them this Activity.</p><div class="price">1 action · 25 per person <span>· max four</span></div>${button('Arrange medical care','recover','',isActionDisabled()||!G.officer(state,activeOfficer).skills.Medicine||!crew.some(m=>m.status==='Recovering'),'secondary')}</div><div class="action-card"><h3>Work the Network</h3><p>Find a new set of candidates through Diplomacy. They remain hireable through the next turn, then move on.</p><div class="price">1 action <span>· no cash cost</span></div>${button('Search for recruits','network-recruits','',isActionDisabled(),'secondary')}</div></div></section>`;$('workspace').innerHTML=html;}
function personCard(m){let candidate=m.status==='Candidate';return `<article class="person"><div class="person-top"><span class="avatar ${esc(m.color)}">${esc(m.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.role)}</p></div></div>${badge(m.status,statusName(m))} ${badge('pending',m.rarity||'Common')}<p class="bio">${esc(m.bio)}</p><div class="person-metrics"><b>Level ${m.level}</b><span>${credits(G.assignmentWage(m))}/assignment · ${m.employment==='retained'?G.retainer(m)+'/month retainer':'Free Agent'}</span><span>Loyalty ${m.loyalty}</span></div><div class="bar"><i style="width:${m.xp/10}%"></i></div><div class="status-detail">${m.xp}/1,000 XP · listed skills ${G.rank(m.level)} · unlisted skills untrained</div><div class="skill-tags">${Object.keys(m.skills).map(k=>`<span>${esc(k)} +${G.skill(m,k)}</span>`).join('')}</div>${candidate?`<p class="status-detail">Hiring ${2*G.wage(m.level)} · expires end Turn ${m.expires} · starts next turn</p>${button('Hire Free Agent · 1 action','hire',`data-id="${m.id}" data-employment="free"`,isActionDisabled()||state.cash<2*G.wage(m.level))}${button('Hire Retained · 1 action','hire',`data-id="${m.id}" data-employment="retained"`,isActionDisabled()||state.cash<2*G.wage(m.level)||state.reputation<20,'secondary')}<p class="table-note">Retained access: Reputation20. Quoted retainer${5*Math.ceil(G.wage(m.level)*.5/5)}/month from next Upkeep; assignment${5*Math.ceil(G.wage(m.level)*.8/5)}.</p>`:m.level>=5&&!m.leaderFeat?button('Choose Level 5 Leader Feat','leader-feat',`data-id="${m.id}"`,false,'secondary'):m.leaderFeat?`<p class="status-detail">Leader Feat: ${esc(G.leaderFeats.find(f=>f.id===m.leaderFeat).name)} · active only if appointed leader</p>`:''}</article>`;}

function renderDevelopment(){const b=G.operating(state),slots=G.locationSlots(state,b.id),active=state.projects.filter(p=>!p.done);let html=`<div class="section-heading"><h2>Bases & upgrades</h2><span class="small-label">${state.bases.filter(b=>b.status!=='Closed').length} LOCATIONS · ONE SHARED ACTION POOL</span></div><div class="base-context"><label for="operating-base">Operating location</label><select id="operating-base">${state.bases.filter(b=>b.status==='Operational').map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)}${x.id===state.primaryBase?' · Headquarters':''}</option>`).join('')}</select><p>Location selection changes the local roster and market. Use its chief or a staffed Comms Hub for remote leadership.</p></div><div class="base-grid">${state.bases.map(baseCard).join('')}</div><section class="subsection"><div class="subsection-head"><h3>Purchase a new base</h3><p>Unlock at Guild Level 4. Empty turnkey properties; one purchase action.</p></div><div class="action-grid">${Object.entries(G.V.base_market).map(([type,v])=>`<div class="action-card"><p class="eyebrow">OWNED PROPERTY</p><h3>${esc(v.name)}</h3><p>${type==='field_hq'?'A mobile operations rig, not a starship.':type==='permanent_hq'?'More space for dedicated facilities.':'Regional access with a funded local chief.'}</p><div class="price">${credits(v.purchase_price)} credits <span>· ${v.slots} upgrade slots</span></div><p class="status-detail">${v.property_monthly}/month property upkeep${type==='outpost'?' +125 chief salary; separate100-credit hire':''}. Possession next Upkeep.</p>${button('Review purchase · 1 action','buy-base',`data-type="${type}"`,isActionDisabled()||state.guildLevel<4||state.cash<v.purchase_price,'secondary')}${state.cash<v.purchase_price?'<p class="table-note">Save '+credits(v.purchase_price-state.cash)+' more credits, or use the Expansion test preset.</p>':''}</div>`).join('')}</div></section><section class="subsection"><div class="subsection-head"><h3>Install at ${esc(b.name)}</h3><p>New installations unlock at Guild Level 2. ${slots.free} free slots · ${slots.reserved} reserved · ${active.length}/${G.V.project_capacity[state.guildLevel]} shared projects</p></div><div class="action-grid">${['training_suite','infirmary','recruitment_office','comms_hub'].map(type=>{const v=G.V.facilities[type],q=G.facilityQuote(type),installed=state.facilities.some(f=>f.type===type&&f.baseId===b.id),building=active.some(p=>p.type===type&&p.baseId===b.id);return `<div class="action-card"><h3>${esc(v.name)}</h3><p>${esc(v.description)}</p><div class="price">${credits(q.cost)} funded <span>· includes manager · ${q.turns} turn${q.turns>1?'s':''}</span></div><div class="cost-breakdown"><span>Asset upkeep <b>${q.assetMonthly}</b></span><span>${esc(v.staff_name)} <b>${q.staffMonthly}</b></span><span>Total each month <b>${q.overhead}</b></span></div><p class="status-detail">One slot · Transferable${v.transferable} · staff due on activation, maintenance next boundary.</p>${button(installed?'Installed':building?'Under construction':'Review expansion · 1 action','project',`data-type="${type}"`,isActionDisabled()||state.guildLevel<2||state.cash<q.cost||installed||building||slots.free<1||!G.baseOperational(state,b)||active.length>=G.V.project_capacity[state.guildLevel],'secondary')}</div>`;}).join('')}</div></section>`;
if(active.length)html+=`<section class="subsection"><h3>Funded projects</h3>${active.map(p=>`<div class="panel"><h3>${esc(G.V.facilities[p.type].name)}</h3><p>At ${esc(G.base(state,p.baseId).name)} · completes Turn${p.due}. Manager already funded; no repeat monthly manager charge.</p></div>`).join('')}</section>`;
html+=`<section class="subsection"><h3>Other guild development</h3><div class="action-grid"><div class="action-card"><h3>Promote the Guild</h3><p>Diplomacy versus DC${G.administrativeDC(state)}. Reputation −1/0/+2/+4 by degree. One public promotion or Sector Campaign per turn.</p><div class="price">1 action ·50 credits</div>${button('Promote','promote','',isActionDisabled()||state.cash<50||state.promotionTurn===state.turn||state.campaignTurn===state.turn,'secondary')}</div><div class="action-card"><h3>Optimize Infrastructure</h3><p>Trained Crafting. Save10%/20% on one facility’s next asset-maintenance bill. Payroll and rent stay separate.</p>${button('Plan maintenance','optimize','',isActionDisabled()||!G.officer(state,activeOfficer).skills.Crafting||!state.facilities.length,'secondary')}</div></div><p>Guild Feats at Levels 3, 5, 7 and 9. Development: Level 2 installations/ordinary finance; Level 4 property/secured finance; Levels 6/8/10 allow 3/4/5 simultaneous projects.</p><p>Earned Guild Feats: ${state.guildFeats.length?state.guildFeats.map(id=>esc(G.guildFeats.find(f=>f.id===id).name)).join(', '):'none'}. Shared actions${G.actionPool(state)}; additional properties and chiefs never add actions.</p></section>`;$('workspace').innerHTML=html+advancedPanel()+milestonePanel()+heroPanel()+financePanel();
}
function tableRanges(rows,label){let previous=0;return rows.map(([upper,value])=>{const lower=previous+1;previous=upper;return `${lower===upper?upper:lower+'–'+upper}: ${esc(label(value))}`;}).join('<br>');}
function discoveryPanel(){const d=state.lastDiscovery;if(!d)return '';return `<section class="admin-result"><p class="eyebrow">LAST NETWORK DISCOVERY · TURN${d.turn}</p><h3>${G.names[d.degree]} · ${d.results.length} ${d.mode==='contracts'?'contract leads':'recruits'}</h3><p>Target Level${d.targetLevel}${d.countRoll!==null?' · Quantity d20 '+d.countRoll:''}. Finding options does not hire or secure them.</p><div class="invoice-scroll"><table class="invoice-table"><thead><tr><th>Result</th><th>Level / quality</th><th>Table dice</th></tr></thead><tbody>${d.results.map(x=>`<tr><td>${esc(x.name)}${x.notes?.length?'<small>'+esc(x.notes.join('; '))+'</small>':''}</td><td>L${x.level}${x.kind?' ·'+G.V.contracts[x.kind].label:''} ·${esc(x.rarity)}</td><td>Level d20 ${x.rolls.level}${x.kind?' · difficulty d20 '+x.rolls.difficulty:''} · rarity d20 ${x.rolls.rarity} · profile d20 ${x.rolls.profile}${x.rolls.skill?' · skill d20 '+x.rolls.skill:''}</td></tr>`).join('')||'<tr><td colspan="3">No options discovered on this Critical Failure.</td></tr>'}</tbody></table></div><p class="table-note">Contract rarity currently describes availability; difficulty controls payout and danger. Specialist recruits have one extra listed skill. All table rolls are visible here and in exported notes.</p></section>`;}
function rerollNote(r){return r.originalRoll?`<p class="hero-note">${esc(r.heroSpent.name)} spent1 Hero Point: original d20 ${r.originalRoll.face} (${G.names[r.originalRoll.degree]}) → reroll d20 ${r.face} (${G.names[r.degree]}). Second result kept.</p>`:'';}
function heroRerollControls(j){const r=j.rolls[state.operations.pendingReview.phase],pcs=G.heroPCs(state),eligible=pcs.filter(o=>o.heroPoints>0);if(r.heroSpent)return '<p class="hero-note">Hero Point used on this check; accept the second result to continue.</p>';return `<div class="hero-reroll"><h3>Spend a PC's Hero Point?</h3><p>Reroll this phase once before accepting it. Same modifier and DC; you must keep the second result, even if worse. Any PC can fund this guild mission reroll.</p><label for="hero-payer">PC paying the point</label><select id="hero-payer">${pcs.map(o=>`<option value="${o.id}" ${o.id===eligible[0]?.id?'selected':''} ${o.heroPoints<1?'disabled':''}>${esc(o.name)} · ${o.heroPoints} remaining</option>`).join('')}</select>${button('Spend1 Hero Point · reroll d20','hero-reroll','',!eligible.length,'secondary')}${!eligible.length?'<p>No PC Hero Points remain this session.</p>':''}</div>`;}
function heroPanel(){return `<section class="subsection"><h3>Player Hero Points · table session${state.heroSession}</h3><p>Each PC starts a table session with1; maximum3. Guild Turns do not refresh these. Use the phase review screen to reroll a mission check once and keep the second result.</p><div class="action-grid">${G.heroPCs(state).map(o=>`<div class="action-card"><h3>${esc(o.name)} · ${o.heroPoints}/3</h3>${button('GM award +1','hero-award',`data-id="${o.id}"`,o.heroPoints>=3,'quiet')}</div>`).join('')}</div>${button('Start a new table session','hero-session-dialog','',!!state.operations?.pendingReview,'secondary')}<p class="table-note"><b>Exceptional performance:</b> all three final phase results are Critical Successes. The GM may award one Hero Point to one PC for meaningful leadership or preparation. Routine/Trivial work normally earns no such award; no automatic cash or XP bonus. GM controls model session awards, not monthly guild income. Spending a PC point on an NPC contract phase is this subsystem's custom rule; other guild checks do not yet have a Hero Point review step.</p></section>`;}

function financePanel(){const revenue=G.averageRevenue(state),loans=state.loans||[];return `<section class="subsection"><div class="subsection-head"><h3>Guild financing</h3><p>Recorded monthly client receipts: ${credits(Math.floor(revenue))}. Combined new-loan payment ceiling: ${credits(Math.floor(revenue*.3))}/month.</p></div><div class="action-grid">${['unsecured','secured'].map(type=>{const secured=type==='secured',level=secured?4:2;return `<div class="action-card"><h3>${secured?'Secured property loan':'Unsecured guild loan'}</h3><p>Guild Level ${level} · ${secured?'1% monthly interest; pledge one operational owned base, up to 70% of its price.':'2% monthly interest; total unsecured principal capped at 1,000 × Guild Level.'} Twelve monthly principal installments, with interest on the remaining balance.</p><p>Nonnegative Reputation, no arrears, and total debt payments within 30% of recorded receipts from up to three completed turns. Loan proceeds do not count as revenue.</p>${button('Review financing · 1 action','loan-dialog',`data-type="${type}"`,isActionDisabled()||state.guildLevel<level,'secondary')}</div>`;}).join('')}</div>${loans.length?`<table class="invoice-table"><thead><tr><th>Agreement</th><th>Principal remaining</th><th>Next payment</th><th>Status</th><th></th></tr></thead><tbody>${loans.map(l=>{const q=G.loanDue(state,l);return `<tr><td>${esc(l.id)} · ${esc(l.type)}${l.collateral?'<small>Pledged: '+esc(G.base(state,l.collateral).name)+'</small>':''}</td><td>${credits(l.remaining)}</td><td>${q.principal} principal + ${q.interest} interest</td><td>${esc(l.status)}</td><td>${button('Repay principal','repay-dialog',`data-id="${l.id}"`,state.phase!=='activity'||l.remaining<=0||state.cash<=0,'quiet')}</td></tr>`;}).join('')}</tbody></table>`:''}<p class="table-note">Repayment is routine and costs no action. A missed installment creates creditor arrears and Delinquency; uncured at the next boundary means Default and blocks finance. Secured collateral remains pledged; foreclosure and negotiated restructuring require GM adjudication in this prototype. Interest continues while principal remains unpaid.</p></section>`;}
function financeDialog(type){const secured=type==='secured',owned=state.bases.filter(b=>b.type!=='leased_station_hq'&&b.status==='Operational');show('Secure '+type+' financing',`<p>One shared action. Proceeds arrive now; first payment is due at the next Upkeep. Twelve principal installments, plus ${secured?'1':'2'}% monthly interest on outstanding principal. No loan fee or early repayment penalty.</p><div class="form-row"><label for="loan-amount">Amount (whole hundreds)</label><input id="loan-amount" type="number" min="100" step="100" value="1000"></div>${secured?`<div class="form-row"><label for="loan-collateral">Owned property to pledge</label><select id="loan-collateral">${owned.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div>`:''}<div id="loan-preview" class="quote-box"></div><p>First missed bill: Delinquent. Uncured next boundary: Default; new finance blocked. Collateral is pledged pending a GM creditor remedy. Existing principal and arrears are never erased by another application.</p>${dialogActions('Fund loan · 1 action','loan-confirm',`data-type="${type}"`)}`);dialogData={loanType:type};updateLoanQuote();}
function updateLoanQuote(){if(!dialogData?.loanType)return;const node=$('loan-preview');try{const q=G.loanQuote(state,dialogData.loanType,Number($('loan-amount').value),$('loan-collateral')?.value||null);node.textContent=`Approved terms: ${q.amount} received. First Upkeep: ${q.installmentPrincipal} principal + ${q.interest} interest = ${q.payment}. Known next Upkeep with this loan: ${G.forecast(state)+q.payment}. Approval reflects past receipts; future work is not guaranteed.`;}catch(e){node.textContent=e.message;}}

function baseCard(b){const slots=G.locationSlots(state,b.id),fs=state.facilities.filter(f=>f.baseId===b.id&&!f.returnedAt),operational=G.baseOperational(state,b);return `<article class="base-card ${b.id===state.primaryBase?'headquarters':''}"><p class="eyebrow">${b.type==='leased_station_hq'?'LEASED':'OWNED'} · ${esc(b.region)}</p><h3>${esc(b.name)}</h3>${badge(operational?'accepted':'pending',b.id===state.primaryBase?'Headquarters · '+b.status:b.status)}<p class="base-cost">${b.monthly}<small>property credits / month</small></p><p>${slots.used}/${slots.total} slots installed · ${slots.reserved} reserved · ${slots.free} free.</p>${b.status==='Pending'?`<p>Possession Turn${b.readyAt}.</p>`:''}${b.endsAt?`<p class="bad-text">Lease ends at Upkeep${b.endsAt}; paid rent is not refunded.</p>`:''}${b.type==='outpost'?`<p>Chief: ${b.chief?esc(b.chief.name)+' ·125/month · '+(b.chief.paidTurn===state.turn?'funded':'awaiting payroll'):'vacant — local services unavailable'}</p>${!b.chief?button('Hire chief ·100 ·1 action','chief',`data-id="${b.id}"`,isActionDisabled()||state.cash<100,'secondary'):''}`:''}${fs.map(f=>`<div class="installed-row"><b>${esc(G.V.facilities[f.type].name)}</b><small>${f.landlordOwned?'Landlord-owned · stays here · ':''}${f.transfer?'In transit until Turn'+f.transfer.due:G.facilityOperational(state,f)?'Staffed & operational':'Service inactive'} · ${G.facilityQuote(f.type).overhead}/month</small></div>`).join('')||'<p class="table-note">No installed upgrades.</p>'}${b.status==='Operational'&&b.type!=='outpost'&&b.id!==state.primaryBase?button('Review HQ relocation ·1 action','relocate',`data-id="${b.id}"`,isActionDisabled(),'secondary'):''}${operational&&b.id!==G.operating(state).id?button('Transfer local crew here','transfer',`data-id="${b.id}"`,isActionDisabled(),'quiet'):''}</article>`;}
function renderUpkeep(){const u=state.upkeep,total=u.invoice.reduce((n,l)=>n+l.amount,0),paid=u.invoice.reduce((n,l)=>n+l.paid,0),remaining=total-paid,next=G.forecast(state);let html=`<section class="stage-card upkeep-review"><p class="eyebrow">UPKEEP / REVIEW THE OPERATING BUDGET</p><h2>${u.settled?'Payments recorded. Choose the next commitments.':'Keep the operation running.'}</h2><p>Base expenses, facility services and retainers are due before this month’s work. Automatic payment funds current monthly obligations first, then older arrears. Use individual Pay buttons to choose a different priority. Prior Events receipts are already in treasury; future contracts are not guaranteed income.</p><div class="quote-metrics"><div><strong>${credits(u.cashBefore??state.cash)}</strong><small>CASH ENTERING UPKEEP</small></div><div><strong>${credits(total)}</strong><small>INVOICE TOTAL</small></div><div><strong>${credits(u.settled?state.cash:Math.max(0,state.cash-remaining))}</strong><small>${u.settled?'CURRENT CASH':'AFTER AVAILABLE PAYMENTS'}</small></div></div>${state.cash<remaining&&!u.settled?`<p class="shortfall">Shortfall: ${credits(remaining-state.cash)} credits. Choose which bill to pay first, then record remaining unpaid obligations. Unfunded staff provide no service; arrears stay owed.</p>`:''}<div class="invoice-scroll"><table class="invoice-table"><thead><tr><th>Obligation</th><th>Due</th><th>Paid</th><th></th></tr></thead><tbody>${u.invoice.map(l=>`<tr><td>${esc(l.label)}${l.baseId?'<small>'+esc(G.base(state,l.baseId).name)+'</small>':''}</td><td>${credits(l.amount)}</td><td>${credits(l.paid)}</td><td>${!u.settled&&l.paid<l.amount?button('Pay','pay-line',`data-id="${esc(l.id)}"`,state.cash<=0,'quiet'):l.paid===l.amount?'Paid':'Unpaid'}</td></tr>`).join('')||'<tr><td colspan="4">This interval was paid before the update; no repeat charges.</td></tr>'}</tbody></table></div>${!u.settled?`<div class="button-row">${button(state.cash>=remaining?'Pay remaining bills · '+credits(remaining):'Fund current bills first & record arrears','settle-upkeep')}${button('Review bases & staff','view-bases','',false,'quiet')}</div>`:''}<div class="upkeep-forecast"><b>Known next Upkeep: ${credits(next)} credits</b><span>Includes scheduled possessions and staffing. Cash covers approximately ${next?Math.floor((u.settled?state.cash:Math.max(0,state.cash-remaining))/next):0} further bills at this cost; mission wages, purchases and training are excluded.</span></div>${u.changes?.length?`<details class="upkeep-changes" open><summary>Personnel & project updates</summary>${u.changes.map(t=>'<p>'+esc(t)+'</p>').join('')}</details>`:''}${state.facilities.filter(f=>!f.transfer&&!f.returnedAt&&G.base(state,f.baseId).status==='Operational').map(f=>`<div class="staff-renewal"><div><b>${esc(G.V.facilities[f.type].name)} · ${esc(G.base(state,f.baseId).name)}</b><small>${esc(f.staff.name)} ·${f.staff.monthly}/month · ${f.staff.active?'renewing':'paused'}. Month-to-month service; asset costs remain due.</small></div>${!u.settled?button(f.staff.active?'Pause this month':'Renew service','renew-staff',`data-id="${f.id}" data-active="${f.staff.active?'false':'true'}"`,u.invoice.some(l=>l.reference===f.id&&l.type==='staff'&&l.paid>0),'quiet'):''}</div>`).join('')}${u.settled?u.choices.map(upkeepChoice).join(''):''}${u.settled&&!u.choices.length?`<div class="button-row">${button('Open Activity · '+G.actionPool(state)+' shared actions →','finish-upkeep')}</div>`:''}<p class="table-note">Routine Upkeep uses no Guild Actions. No automatic eviction, contract termination or Loyalty penalties for unpaid retainers are simulated; unpaid services and arrears are visible.</p></section>`;$('stage-panel').innerHTML=html;}

function renderLog(){let inflow=state.ledger.filter(e=>e.amount>0).reduce((a,e)=>a+e.amount,0),outflow=-state.ledger.filter(e=>e.amount<0).reduce((a,e)=>a+e.amount,0);$('workspace').innerHTML=`<div class="section-heading"><h2>Operations log</h2><button data-do="export" class="quiet">Copy notes</button></div><div class="ledger-summary"><div><b>${credits(inflow)}</b>client receipts</div><div><b>${credits(outflow)}</b>actual spending</div><div><b>${credits(state.cash)}</b>treasury</div></div><details class="panel"><summary>Cash ledger · every actual receipt and payment</summary><table class="ledger-table"><thead><tr><th>Turn</th><th>Entry</th><th>Credits</th></tr></thead><tbody>${state.ledger.slice().reverse().map(e=>`<tr><td>T${e.turn}</td><td>${esc(e.note)}</td><td class="${e.amount>0?'good-text':'bad-text'}">${e.amount>0?'+':''}${credits(e.amount)}</td></tr>`).join('')}</tbody></table><p class="table-note">Starting funds${credits(state.initialCash)} +receipts−actual spending=treasury. Arrears are recorded obligations, not negative cash.</p></details>${state.jobs.filter(j=>j.settled).slice(-6).reverse().map(missionResults).join('')}${state.log.map(l=>`<article class="log-entry ${esc(l.kind)}"><span class="log-turn">TURN ${l.turn}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p></div></article>`).join('')}`;}
function show(title,html,kicker='GUILD OPERATIONS'){modalType=title;$('modal-kicker').textContent=kicker;$('modal-content').innerHTML=`<h2>${esc(title)}</h2>${html}<p id="modal-error" class="modal-error" role="alert"></p>`;if(!$('modal').open)$('modal').showModal();}
function close(){$('modal').close();modalType=null;dialogData=null;}
function dialogActions(label,action,extra=''){return `<div class="modal-actions">${button('Cancel','close','',false,'quiet')}${button(label,action,extra)}</div>`;}
function checkedIds(){return [...document.querySelectorAll('#modal input[name="crew"]:checked')].map(x=>x.value);}
function operationLock(c){return c.preparation?.expires>=state.turn&&c.preparation.lock||c.contingency?.expires>=state.turn&&c.contingency.lock||null;}
function lockedCrewOptions(members,c){const lock=operationLock(c);return '<div class="crew-select">'+members.map(m=>`<label class="crew-option"><input type="checkbox" name="crew" value="${m.id}" ${!lock||lock.ids.includes(m.id)?'checked':''}><span><b>${esc(m.name)}</b><small>Level ${m.level} · ${esc(m.role)}</small></span></label>`).join('')+'</div>';}
function crewOptions(members,all=true){return `<div class="crew-select">${members.map(m=>`<label class="crew-option"><input type="checkbox" name="crew" value="${m.id}" ${all?'checked':''}><span><b>${esc(m.name)}</b><small>Level ${m.level} · ${esc(m.role)}</small></span></label>`).join('')}</div>`;}
function details(cid){const c=G.offer(state,cid),v=G.contractRule(c);show(c.name,`<p class="modal-description">${esc(c.description)}</p><p class="modal-description"><b>NPC contract resolution.</b> <b>${esc(G.completionRule(c))}</b>. Resolves in this turn’s Events after deployment. Offer expires end Turn ${c.expires}. ${c.kind==='exclusive'?'Accepted completion deadline: this turn’s Events; deploy immediately.':'Ordinary expiry alone has no Reputation penalty.'}</p><div class="quote-box">${c.skills.map((k,p)=>`<div class="check-line"><b>${G.phases[p]} · ${esc(k)}</b><span>base DC${G.V.level_dc[c.level]+v.dc_offset}</span></div>`).join('')}</div><p class="modal-description">Crew size min3 / recommended4 / max6. Three different operatives lead the three checks; their automatic support can still help other phases. Recommended Level${c.level}; minimum Squad Level${Math.max(1,c.level-2)}. Squad Level=floor average. Each extra operative above recommended grants +1 circumstance to every phase; use the highest circumstance bonus. Smaller squads retain +1 DC per missing operative, cap+2. Base client cash ${credits(G.contractPayout(c.level,v.payout_factor))}; each extra operative reduces it by10%. Overlevel discounts also apply, combined minimum50%; operative XP is unchanged. Relative Guild threat changes Guild XP.</p><p class="modal-description">XP ${v.participation_xp} participation +${v.completion_xp} completion each. Guild XP ${G.contractThreat(state,c).xp} on completion (${G.contractThreat(state,c).label} for Guild Level ${state.guildLevel}). This rating is organizational experience; crew risk uses the printed DCs and modifiers. Reputation +${v.reputation_success}/${v.reputation_failure}. Required recovery ${v.mandatory_recovery} turn${v.mandatory_recovery===1?'':'s'}.</p><p class="modal-description"><b>Risk card:</b> ${esc(G.consequencePreview(c))}</p><hr><p class="modal-description"><b>Phase consequences:</b> Critical Success +1 next phase; Failure−1 next; Critical Failure−2 all remaining and1 squad recovery. Recovery sources use the longest duration. Leads are locked before the first check; no support or overall roll.</p><div class="modal-actions">${button('Got it','close')}</div>`,'CONTRACT CARD');}
function secureDialog(cid){const c=G.offer(state,cid);const eligible=c.kind==='standard'&&state.contacts.includes(c.client)&&!state.trustedUsed&&(state.guildFeats.includes('trusted')||state.guildFeats.includes('standing'));show('Secure the contract',`<p class="modal-description"><b>${esc(c.name)}</b> · ${esc(c.client)}. ${G.acquisitionCost(state,c,false).cost===0?'Acquisition costs no action; any applicable shared waiver is consumed.':'Acquisition costs one action from the shared pool.'} Deployment is a separate, routine staff assignment.</p>${eligible?`<label class="inline-choice"><input id="use-waiver" type="checkbox"><span>Use Trusted Client’s free acquisition this turn. One ordinary Standard contract from a known contact.</span></label>`:''}${c.kind==='exclusive'?'<p class="modal-description bad-text">Binding deadline: deploy now and finish next boundary. Accepting without ready staff will breach the contract.</p>':''}${dialogActions('Secure & plan crew','secure-confirm',`data-id="${cid}"`)}`);}
function deployDialog(cid,planMode=null){const c=G.offer(state,cid);const members=G.localMercs(state).filter(m=>workReady(m)&&m.dispatchedTurn!==state.turn);dialogData={cid,planMode};show(planMode==='briefing'?'Prepare an Operations Briefing':planMode==='contingency'?'Establish an Extraction Contingency':'Assign the operation',`<p class="modal-description">${esc(c.name)}. Select3–6 Available operatives; each lead may take only one of the three checks, then declare all three leads. Their relevant supporters contribute automatically. ${planMode?'This plan locks the squad, all leads and optional leader. '+(planMode==='briefing'?'Operations Officer, 2 shared actions, 25 credits/person. Survival or Computers; success +1 circumstance to all phases, critical success +2. Replaces Recon.':'Operations Officer, 3 shared actions, 25% of quoted wages rounded up to 5. Success protects once, critical success twice; Missing-to-Recovering first, then half repairs.'):'Deployment spends no Guild Action.'}</p>${members.length?lockedCrewOptions(members,c):'<div class="empty">No Available crew. Finish training/recovery or wait for onboarding.</div>'}<div class="lead-grid">${c.skills.map((k,p)=>`<div class="form-row"><label for="lead-${p}">${G.phases[p]} · ${esc(k)}</label><select id="lead-${p}" data-lead="${p}"></select></div>`).join('')}</div><div id="leader-row" class="form-row"><label for="squad-leader">Optional Level5+ squad leader</label><select id="squad-leader"><option value="">No appointed leader</option></select></div><div id="deployment-quote" class="quote-box"></div>${dialogActions(planMode?'Fund plan · '+(planMode==='briefing'?2:3)+' actions':'Deploy squad · routine',planMode?'plan-confirm':'deploy-confirm',`data-id="${cid}" data-mode="${planMode||''}"`)}`,'DEPLOYMENT PLAN');updateDeployment(true);}
function updateDeployment(rebuild=false){if(!dialogData?.cid||!$('deployment-quote'))return;const c=G.offer(state,dialogData.cid),ids=checkedIds(),members=ids.map(i=>G.merc(state,i));if(rebuild){const lock=operationLock(c),recommended=lock?.leads||G.chooseLeads(state,c,ids);for(let p=0;p<3;p++){const sel=$('lead-'+p);sel.innerHTML=members.map(m=>`<option value="${m.id}" ${!G.leadEligible(c,m,p)?'disabled':''}>${esc(m.name)} ·${G.leadRank(m,c.skills[p])} +${G.skill(m,c.skills[p])}</option>`).join('');sel.value=recommended?.[p]||'';}let sel=$('squad-leader'),old=sel.value;const leaders=members.filter(m=>m.level>=5&&m.leaderFeat);sel.innerHTML='<option value="">No appointed leader</option>'+leaders.map(m=>`<option value="${m.id}">${esc(m.name)} ·${esc(G.leaderFeats.find(f=>f.id===m.leaderFeat).name)}</option>`).join('');sel.value=leaders.some(m=>m.id===(lock?.leader||old))?(lock?.leader||old):'';$('leader-row').classList.toggle('hidden',!leaders.length);}try{const q=G.quote(state,c,ids,[0,1,2].map(p=>$('lead-'+p).value),$('squad-leader').value||null);$('deployment-quote').className='quote-box';$('deployment-quote').innerHTML=`<div class="quote-metrics"><div><strong>${q.squadLevel}</strong><small>FLOOR-AVERAGE LEVEL</small></div><div><strong>${credits(q.payout)}</strong><small>SUCCESSFUL CLIENT CASH</small></div><div><strong>${credits(q.pay)}</strong><small>FROZEN SQUAD WAGES</small></div></div><p><b>${q.guildAward.label} for Guild Level ${q.guildAward.guildLevel} · ${q.guildAward.xp} Guild XP on completion.</b> Crew danger is shown by the actual checks below.</p>${q.checks.map((r,p)=>`<div class="check-line"><span>${esc(r.phase)} ·${esc(r.leadName)}<small> ${esc(c.skills[p])} ·minimum ${esc(c.minimumLeadRanks?.[p]||G.contractRule(c).minimum_lead_rank||'Untrained')}</small></span><b>+${r.skillBonus} skill +${r.support} support${r.circumstance?' '+(r.circumstance>0?'+':'')+r.circumstance+' circumstance':''} /DC${r.dc}</b></div>`).join('')}<p class="table-note"><b>Completion: ${esc(G.completionRule(c))}</b> Level${c.level} DC${G.V.level_dc[c.level]} ${G.contractRule(c).dc_offset>=0?'+':''}${G.contractRule(c).dc_offset} difficulty. Three distinct leads; no additional rolls. ${esc(G.consequencePreview(c))}</p>`;const mode=dialogData.planMode,cost=mode==='briefing'?25*ids.length:mode==='contingency'?5*Math.ceil(q.pay*.25/5):0;if(mode)$('deployment-quote').innerHTML+='<p><b>Plan price: '+cost+' credits · '+(mode==='briefing'?2:3)+' shared actions</b></p>';document.querySelector('[data-do="'+(mode?'plan-confirm':'deploy-confirm')+'"]').disabled=!!mode&&(state.cash<cost||state.actions<(mode==='briefing'?2:3));}catch(e){$('deployment-quote').className='quote-box error';$('deployment-quote').textContent=e.message;document.querySelector('[data-do="'+(dialogData.planMode?'plan-confirm':'deploy-confirm')+'"]').disabled=true;}}

function networkDialog(mode){const cap=Math.min(20,2*state.guildLevel+1),crew=G.localMercs(state).filter(workReady),target=crew.length?Math.min(cap,Math.max(1,Math.floor(crew.reduce((n,m)=>n+m.level,0)/crew.length))):1;show(mode==='recruits'?'Find recruitment candidates':'Find contract leads',`<p class="modal-description">${esc(G.officer(state,activeOfficer).name)} rolls Diplomacy against the searched level's DC. One action. Failure, Success and Critical Success each generate three options. Critical Failure rolls d20:1–10 none,11–20 one. Better degrees shift level and rarity${mode==='contracts'?', plus difficulty':''}; you choose which offers to pursue.</p><div class="form-row"><label for="search-level">Target level ·1–${cap}</label><input id="search-level" type="number" value="${target}" min="1" max="${cap}"></div><p>Generated levels are clamped to1–${cap}. Higher difficulty means more risk, not a guaranteed better choice. Hiring or securing remains a separate action.</p><details><summary>Discovery tables · each result rolls independently</summary><div class="invoice-scroll"><table class="invoice-table"><thead><tr><th>Check outcome</th><th>Quantity</th><th>Level d20</th><th>${mode==='contracts'?'Difficulty d20':'Candidate skills'}</th><th>Rarity d20</th></tr></thead><tbody>${G.names.map((name,d)=>`<tr><td>${name}</td><td>${d===0?'0 or1':'3'}</td><td>${tableRanges(G.V.discovery.level_offsets[d],x=>x===0?'target':`target${x>0?'+':''}${x}`)}</td><td>${mode==='contracts'?tableRanges(G.V.discovery.difficulty[d],x=>G.V.contracts[x].label):'Common: profile; Uncommon:+1 moderate skill; Rare:+1 high skill'}</td><td>${tableRanges(G.V.discovery.rarity[d],x=>x)}</td></tr>`).join('')}</tbody></table></div></details>${dialogActions('Roll Diplomacy ·1 action','network-confirm',`data-mode="${mode}"`)}`);}

function selectPersonnel(mode){const training=mode==='train'||mode==='intensive';const eligible=G.localMercs(state).filter(m=>training?workReady(m):mode==='recover'?m.status==='Recovering':['Available','Recovering'].includes(m.status));const title={train:'Commit a training cohort',intensive:'Run an Intensive Training Block',morale:'Recognize your people',recover:'Treat returned personnel'}[mode];show(title,`<p class="modal-description">${mode==='intensive'?'Personnel Officer, trained Medicine, 2 shared actions and 50 credits/person; funded Training Suite required. One 30-day block awards 225 operative XP and releases the trainees next turn. Each trainee once per three turns; no consecutive multiplier.':mode==='train'?'One action; commit up to '+G.trainingCapacity(state)+' Available personnel for one30-day block. Cost25/trainee, plus an ordinary50-credit trainer unless a funded suite supplies one. Suite staff payroll is already in Upkeep. You can extend after completion without a new action.':mode==='recover'?'Trained Medicine; one action and25/person, maxfour. Success reduces remaining recovery by1; Critical Success by2. Eligible staff can be Available immediately.':'One action and10/person. Officer Diplomacy versus DC'+G.administrativeDC(state)+'. Loyalty changes−2/+2/+5/+8 by degree. Public Reputation is separate.'}</p>${eligible.length?crewOptions(eligible):'<div class="empty">No eligible personnel for this action.</div>'}<div id="personnel-cost" class="quote-box"></div>${dialogActions('Confirm · '+(mode==='intensive'?2:1)+' actions','personnel-confirm',`data-mode="${mode}"`)}`);dialogData={mode};updatePersonnel();}
function updatePersonnel(){if(!$('personnel-cost')||!dialogData?.mode)return;const selected=checkedIds(),n=selected.length,mode=dialogData.mode;try{let cost=mode==='train'?G.trainingCost(state,selected):mode==='intensive'?G.trainingCost(state,selected)+25*n:n*(mode==='recover'?25:10);$('personnel-cost').textContent=`${n} personnel ·${credits(cost)} funded now${mode==='train'?' ·150 XP each at next Upkeep':mode==='intensive'?' ·225 XP each at next Upkeep':''}`;const confirm=document.querySelector('[data-do="personnel-confirm"]');if(confirm)confirm.disabled=n===0||state.cash<cost||(mode==='train'||mode==='intensive')&&n>G.trainingCapacity(state)||mode==='intensive'&&state.actions<2;}catch(e){$('personnel-cost').textContent=e.message;const confirm=document.querySelector('[data-do="personnel-confirm"]');if(confirm)confirm.disabled=true;}}

function setupDialog(){show('Start a new playtest',`<p class="modal-description">Choose a starting situation. Each begins at an unpaid Upkeep invoice. Export notes before resetting; your current game will be replaced.</p><div class="form-row"><label for="preset">Starting situation</label><select id="preset"><option value="staffed">Staffed starter ·2,000 cash · leased HQ + landlord Training Suite</option><option value="lean">Lean start ·2,000 cash · empty leased HQ</option><option value="developing" ${state.preset==='developing'?'selected':''}>Developing guild · Level 2 · 2,000 credits · no upgrades</option><option value="expansion">Expansion test ·8,000 cash · Guild Level4 · four Level3 operatives</option></select></div><p class="table-note">Economy test: Level 1 Normal pays900; Free Agents earn110 each (440 for four). Successful wages settle in Events. Existing jobs keep their quotes. Starter first invoice:350 staffed or300 lean. Expansion is an artificial fixture for purchase tests, not evidence of startup balance.</p><div class="form-row"><label for="party-size">PC party members</label><input id="party-size" type="number" value="${state.partySize}" min="1" max="8"></div><div class="form-row"><label for="seed">Scenario seed</label><input id="seed" type="number" value="${state.seed}" min="0" max="999999"></div><div class="form-row"><label for="acquisition">Contract acquisition</label><select id="acquisition"><option value="paid" ${!state.freeAcquisition?'selected':''}>One Guild Action</option><option value="free" ${state.freeAcquisition?'selected':''}>Free · A/B comparison</option></select></div>${dialogActions('Reset & start playtest','reset-confirm')}`,'EXPERIMENT SETTINGS');}

function help(){show('Your first Guild Turn',`<p class="modal-description">You run the guild between adventures. The opening choice is simple: use your shared Guild Actions to secure work, recruit, train, prepare, promote or build. The pool equals PC party members + Guild Level − 1. Let each player choose one action first, then allocate remaining actions together. Choose the PC whose skills apply; there is no officer action cap.</p><ol class="help-list"><li><b>Upkeep:</b> complete training and projects, release scheduled recovery and onboarding, and review the itemized invoice, renew facility staff and record funded payments or arrears. Choose training continuation.</li><li><b>Budget:</b> reset the single shared action pool. New hires become Available next turn.</li><li><b>Commerce:</b> the full game has property/financing choices; review turnkey base purchases and their ongoing costs in Bases & upgrades; financing unlocks at Guild Level 2, and secured finance at Level 4.</li><li><b>Activity:</b> secure a contract, then deploy Available staff without another action. Training and projects complete at later boundaries.</li><li><b>Events:</b> resolve this turn’s deployed contracts with three checks each. Any printed number of successful phases completes the job; no additional required phase. Before accepting a phase, a PC may spend1 Hero Point to reroll and must keep the second result. Collect all payouts before successful wages; choose failed-job pay and MVP. Then resolve one visible monthly scenario. Substantial follow-up waits for next turn.</li><li><b>Advancement:</b> settle Guild XP and choose earned feats. Advance30 days to the next Upkeep.</li></ol><p class="modal-description"><b>Guild progression:</b> 1,000 XP per level; completed relative-threat contracts award Trivial0 / Low60 / Moderate80 / Severe120 / Extreme160. Rating = mission level − Guild Level + complexity (Easy−1, Normal0, Hard/Exclusive+1, Expert+2, Legendary+3). Offsets≤−3:Trivial; −2/−1:Low; 0:Moderate; +1:Severe; +2or more:Extreme. This is a custom organizational rating, not the assigned crew’s combat danger. Quotes freeze at deployment. First funded owned HQ/outpost80 each; first funded facility type30. Multi-action activities use the one shared pool; players may contribute actions jointly. PC administrative modifiers advance with the demo DC benchmark; Foundry will use actual character skills.</p><p class="modal-description"><b>Try this:</b> secure Dock Nine, assign the four starters, then use the remaining actions to find candidates and hire one. Or put half your crew in training and tackle an easier job later. Notice what you cannot do this month.</p><p class="modal-description">Play six months, then copy your notes back into chat. You can continue beyond six turns to test growth. Browser progress saves locally; exported notes preserve your decisions and dice. This demo does not adjudicate the complete tabletop subsystem.</p><div class="modal-actions">${button('Open for business','close')}</div>`,'PLAYTEST GUIDE');}
async function exportNotes(){const text=G.summary(state);try{await navigator.clipboard.writeText(text);notify('Playtest notes copied. Paste them into chat so we can discuss your decisions.');}catch{show('Copy your playtest notes',`<p class="modal-description">Select and copy this text, then paste it into chat.</p><textarea class="readonly-notes" rows="12" readonly>${esc(text)}</textarea><div class="modal-actions">${button('Done','close')}</div>`);}}
function download(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([G.summary(state)],{type:'text/markdown;charset=utf-8'}));a.href=url;a.download='guildmaster-playtest-turn-'+state.turn+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Playtest notes downloaded. Your browser progress remains saved locally.');}

function officerOffice(office){const index=G.heroPCs(state).indexOf(G.officer(state,activeOfficer));return index>=0&&index%4==={command:0,field:2,liaison:3}[office];}
function advancedPanel(){return `<section class="subsection"><h3>Officer activities · shared actions</h3><p>Two or three players can contribute their reserved action to one activity; the named officer leads its single check. Allocate remaining shared actions together.</p><div class="action-grid"><div class="action-card"><h3>Launch a Sector Campaign</h3><p>Commander · Guild3 · Diplomacy. Reputation −2/0/+5/+8. One public campaign or ordinary promotion per turn.</p><div class="price">2 actions ·100 credits</div>${button('Launch campaign','campaign','',state.phase!=='activity'||state.guildLevel<3||state.actions<2||state.cash<100||!officerOffice('command')||state.campaignTurn===state.turn||state.promotionTurn===state.turn,'secondary')}</div><div class="action-card"><h3>Operations Briefing</h3><p>Operations · Guild3. +1/+2 circumstance to all three phases on success/critical success. Costs25/person, locks assignment, replaces Recon.</p><div class="price">2 actions</div><p>Open an accepted contract to select its squad and fund this plan.</p></div><div class="action-card"><h3>Intensive Training Block</h3><p>Personnel · Guild6 · funded suite. One month,225 operative XP/person; automatic release next turn. Each trainee once per three turns.</p><div class="price">2 actions ·50/person</div>${button('Select intensive trainees','intensive','',state.phase!=='activity'||state.guildLevel<6||state.actions<2||!officerOffice('liaison')||!G.localFacility(state,'training_suite'),'secondary')}</div><div class="action-card"><h3>Extraction Contingency</h3><p>Operations · Guild4. Success/critical success provides1/2 protections: Missing becomes Recovering first, then halve repairs. One guild/job/turn.</p><div class="price">3 actions ·25% quoted wages</div><p>Open an accepted contract to fund the locked assignment before deployment.</p></div></div></section>`;}
function milestonePanel(){const m=state.developmentMilestones;return `<section class="subsection"><h3>First-time development milestones</h3><p>First funded owned HQ80 · first funded staffed outpost80 · first funded operational facility of each type30 Guild XP. Repeat properties and facilities provide their normal capabilities without repeating the milestone.</p><p>HQ: ${m.headquarters?'established':'available'} · outpost: ${m.outpost?'established':'available'} · facility categories: ${m.facilities.map(k=>esc(G.V.facilities[k].name)).join(', ')||'none'}. Inherited and previously installed categories count as established, with no retroactive award.</p></section>`;}

document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.tab){tab=b.dataset.tab;renderWorkspace();document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));return;}const action=b.dataset.do;if(!action)return;const cid=b.dataset.id;switch(action){
 
 case 'loan-dialog':financeDialog(b.dataset.type);break;
 case 'loan-confirm':if(run(()=>G.borrow(state,b.dataset.type,Number($('loan-amount').value),activeOfficer,$('loan-collateral')?.value||null))){close();notify('Financing funded. Review its first payment in the next Upkeep.');}break;
 case 'repay-dialog':{const l=state.loans.find(l=>l.id===cid);show('Repay '+l.id,`<p>Routine administration, no action or penalty. Cure this loan’s arrears first. Principal remaining: ${l.remaining}; cash: ${state.cash}.</p><div class="form-row"><label for="repay-amount">Principal to repay</label><input id="repay-amount" type="number" min="1" max="${Math.min(l.remaining,state.cash)}" value="${Math.min(l.remaining,state.cash)}"></div>${dialogActions('Pay principal','repay-confirm',`data-id="${cid}"`)}`);break;}
 case 'repay-confirm':if(run(()=>G.repayLoan(state,cid,Number($('repay-amount').value))))close();break;
 case 'hero-reroll':if(run(()=>G.rerollPhase(state,$('hero-payer').value)))notify('Hero Point spent; the second result is now shown. Review before continuing.');break;
 case 'hero-award':run(()=>G.awardHeroPoint(state,cid));break;
 case 'hero-session-dialog':show('Start a new table session?',`<p>Previous session points expire. Each PC starts with1. This does not advance the Guild Turn or reset missions, cash or actions. Use this only when beginning a new play session.</p>${dialogActions('Start table session','hero-session-confirm')}`);break;
 case 'hero-session-confirm':if(run(()=>G.startHeroSession(state)))close();break;
 case 'view-bases':tab='development';render();break;
 case 'pay-line':run(()=>G.payInvoiceLine(state,cid));break;
 case 'settle-upkeep':run(()=>G.settleUpkeep(state));break;
 case 'renew-staff':run(()=>G.renewStaff(state,cid,b.dataset.active==='true'));break;
 case 'buy-base':{const v=G.V.base_market[b.dataset.type];show('Purchase '+v.name,`<p class="modal-description">${credits(v.purchase_price)} credits and one shared action. Empty turnkey property; no construction manager or second purchase action. Possession next Upkeep.</p><div class="quote-box">Treasury after purchase:${credits(state.cash-v.purchase_price)}. New property expense:${v.property_monthly}/month from possession${b.dataset.type==='outpost'?', plus a separately hired chief at125/month (100 hiring, another action)':''}. Existing lease continues until an actual relocation and notice.</div><p>Slots:${v.slots}. No upgrades included. Owned property still incurs expense while vacant.</p>${dialogActions('Purchase ·1 action','buy-base-confirm',`data-type="${b.dataset.type}"`)}`);break;}
 case 'buy-base-confirm':if(run(()=>G.purchaseBase(state,b.dataset.type,activeOfficer))){close();notify('Purchased. Possession and property upkeep begin next Upkeep.');}break;
 case 'chief':if(run(()=>G.appointChief(state,cid,activeOfficer)))notify('Chief hired. Available next Upkeep;125 monthly salary, no added actions.');break;
 case 'relocate':{const origin=G.base(state,state.primaryBase),target=G.base(state,cid),moving=state.facilities.filter(f=>f.baseId===origin.id&&!f.landlordOwned),turns=Math.max(1,...moving.map(f=>G.V.facilities[f.type].transferable)),cost=moving.reduce((n,f)=>n+G.round(G.V.facilities[f.type].cost*.1),0)+100*turns;show('Relocate to '+target.name,`<p>One shared action; transfer existing owned installations and available local crew. Active training, recovery, onboarding, deployments and construction must finish first.</p><div class="quote-box">Move cost:${cost} including qualified manager. Personnel arrive next Upkeep; installations use TransferableN. Old property charges continue until the lease actually ends. No refund of rent already paid.</div><p>${moving.length} owned upgrades move. Landlord-owned fixtures stay behind.</p>${dialogActions('Fund relocation ·1 action','relocate-confirm',`data-id="${cid}"`)}`);break;}
 case 'relocate-confirm':if(run(()=>G.relocate(state,cid,activeOfficer))){close();notify('Relocation funded. Check transfer dates and overlapping property obligations.');}break;
 case 'transfer':show('Transfer local crew',`<p>One shared action and25/person for local transport. Available at the destination next Upkeep. No same-turn deployment.</p>${crewOptions(G.localMercs(state).filter(workReady))}${dialogActions('Transfer ·1 action','transfer-confirm',`data-id="${cid}"`)}`);break;
 case 'transfer-confirm':if(run(()=>G.transferCrew(state,checkedIds(),cid,activeOfficer))){close();notify('Crew in transit; destination availability next Upkeep.');}break;

 case 'close':close();break;case 'help':help();break;case 'settings':setupDialog();break;case 'export':exportNotes();break;case 'download':download();break;
 case 'details':details(cid);break;case 'secure':secureDialog(cid);break;case 'secure-confirm':{let use=$('use-waiver')?.checked||false;if(run(()=>G.secure(state,cid,activeOfficer,use))){close();deployDialog(cid);}break;}
 case 'deploy':deployDialog(cid);break;case 'deploy-confirm':{const ids=checkedIds(),leads=[0,1,2].map(p=>$('lead-'+p).value),leader=$('squad-leader').value||null;if(run(()=>G.deploy(state,cid,ids,leads,leader))){close();notify('Crew deployed. Resolve the contract during this turn’s Events.');}break;}
 case 'network-recruits':networkDialog('recruits');break;case 'network-contracts':networkDialog('contracts');break;
 case 'network-confirm':{let mode=b.dataset.mode,level=Number($('search-level').value);if(run(()=>G.network(state,activeOfficer,mode,level))){close();tab=mode==='recruits'?'people':'contracts';render();notify(`${G.names[state.lastRoll.degree]}: d20${state.lastRoll.face} +${state.lastRoll.modifier} vs DC${state.lastRoll.dc}. See the new ${mode==='recruits'?'candidates':'leads'} below.`);}break;}
 case 'hire':if(run(()=>G.hire(state,cid,activeOfficer,b.dataset.employment||'free')))notify('Recruited. Available at next Guild Turn, after onboarding.');break;
 case 'intensive':case 'train':case 'morale':case 'recover':selectPersonnel(action);break;
 case 'personnel-confirm':{let mode=b.dataset.mode,ids=checkedIds();if(run(()=>(mode==='intensive'?G.intensiveTraining:G[mode])(state,ids,activeOfficer))){close();notify(mode==='train'?'Training funded. Staff remain unavailable until a completed block is released.':mode==='intensive'?'Intensive training funded. Trainees return next Upkeep with 225 XP.':G.names[state.lastRoll.degree]+': see the resulting staff changes and operations log.');}break;}
 case 'campaign':run(()=>G.sectorCampaign(state,activeOfficer));break;
 case 'briefing':deployDialog(cid,'briefing');break;case 'contingency':deployDialog(cid,'contingency');break;
 case 'plan-confirm':{const mode=b.dataset.mode,ids=checkedIds(),leads=[0,1,2].map(p=>$('lead-'+p).value),leader=$('squad-leader').value||null;if(run(()=>(mode==='briefing'?G.operationsBriefing:G.extractionContingency)(state,cid,ids,leads,activeOfficer,leader))){close();notify('Plan funded; squad and leads are locked. Deploy this job separately using the same assignment.');}break;}
 case 'promote':if(run(()=>G.promote(state,activeOfficer)))notify(`${G.names[state.lastRoll.degree]}: Reputation is now ${state.reputation}.`);break;
 case 'recon':{const c=G.offer(state,cid);show('Prepare one phase',`<p class="modal-description">Trained Computers · one action. Digital Recon adds−1/0/+1/+2 by degree to one named phase. Highest circumstance bonus only; no new mission check.</p><div class="form-row"><label for="recon-phase">Phase to prepare</label><select id="recon-phase">${G.phases.map((p,i)=>`<option value="${i}" ${i===1?'selected':''}>${p} · ${esc(c.skills[i])}</option>`).join('')}</select></div>${dialogActions('Conduct recon · 1 action','recon-confirm',`data-id="${cid}"`)}`);break;}
 case 'recon-confirm':{let p=Number($('recon-phase').value);if(run(()=>G.recon(state,cid,activeOfficer,p))){close();notify('Recon outcome recorded on this card. It applies once to the declared phase.');}break;}
 case 'broker':show('Pursue an Exclusive offer',`<p class="modal-description">Friendly Reputation, Trained Diplomacy,50 credits and one action. Outcomes:0/0/1/2 offers. A lead is not an accepted job; securing remains separate.</p><div class="form-row"><label for="search-level">Target level</label><input id="search-level" type="number" value="1" min="1" max="${Math.min(20,2*state.guildLevel+1)}"></div>${dialogActions('Broker the deal','broker-confirm')}`);break;
 case 'broker-confirm':{let level=Number($('search-level').value);if(run(()=>G.broker(state,activeOfficer,level))){close();notify('Brokerage resolved. Any generated offers appear on the board.');}break;}
 case 'project':{let type=b.dataset.type,q=G.facilityQuote(type);show('Commission '+type.replaceAll('_',' '),`<p class="modal-description">One action and${credits(q.cost)} credits funded now. The price includes${100*q.turns} for a qualified external manager over${q.turns} interval${q.turns>1?'s':''}. One HQ slot is reserved immediately; the project uses the shared cap. Your PC officer is not its manager.</p><div class="quote-box">Completes at Turn${state.turn+q.turns}. Staff payroll${q.staffMonthly} is due on activation; asset upkeep${q.assetMonthly} first bills the following boundary. Recurring total${q.overhead}/month. The first funded operational facility of this type earns30 Guild XP for the guild. Additional copies award no development XP; existing/inherited categories are already established.</div>${dialogActions('Fund & commission','project-confirm',`data-type="${type}"`)}`);break;}
 case 'project-confirm':if(run(()=>G.project(state,b.dataset.type,activeOfficer))){close();notify('Project funded and manager committed. Continuing progress is routine.');}break;
 case 'optimize':show('Plan facility maintenance',`<p class="modal-description">Trained Crafting, one action, no credit fee. Target one owned installation’s next overhead. Savings on asset maintenance are10%/20% on Success/Critical Success, rounded down.</p><div class="form-row"><label for="facility-target">Installation</label><select id="facility-target">${state.facilities.map(f=>`<option value="${f.id}">${esc(f.type.replaceAll('_',' '))} · ${G.V.facilities[f.type].monthly}/month</option>`).join('')}</select></div>${dialogActions('Optimize · 1 action','optimize-confirm')}`);break;
 case 'optimize-confirm':{let fid=$('facility-target').value;if(run(()=>G.optimize(state,fid,activeOfficer))){close();notify('Maintenance outcome recorded for that installation’s next monthly bill.');}break;}
 case 'leader-feat':show('Choose '+G.merc(state,cid).name+'’s Leader Feat',`<p class="modal-description">Earned at Level5. Choose once; only an appointed squad leader’s feat is active.</p><div class="action-grid">${G.leaderFeats.map(f=>`<div class="action-card"><h3>${esc(f.name)}</h3><p>${esc(f.text)}</p>${button('Choose','leader-confirm',`data-id="${cid}" data-value="${f.id}"`,false,'secondary')}</div>`).join('')}</div>`);break;
 case 'leader-confirm':if(run(()=>G.chooseLeaderFeat(state,cid,b.dataset.value)))close();break;
 case 'end':if(state.actions){show('Finish Activity with unused actions?',`<p class="modal-description">${state.actions} shared action${state.actions>1?'s remain':' remains'}. Unused actions expire; they do not become XP. You can leave them unused if staff, funds or action requirements are the real limit.</p>${dialogActions('Proceed to Events','end-confirm')}`);}else run(()=>G.endActivity(state));break;
 case 'end-confirm':if(run(()=>G.endActivity(state)))close();break;
 case 'event-accept':run(()=>G.respondEvent(state,'accept'));break;case 'event-pass':run(()=>G.respondEvent(state,'pass'));break;
 case 'guild-feat':run(()=>G.chooseGuildFeat(state,cid));break;case 'advance':run(()=>G.advance(state));break;
 case 'roll-next':run(()=>{G.acknowledgePhase(state);G.rollPhase(state);});break;
 case 'review-phase':run(()=>G.acknowledgePhase(state));break;
 case 'roll':{if(run(()=>G.rollPhase(state)))notify('Phase result recorded. Review its roll, total, DC, outcome and complication before continuing.');break;}
 case 'upkeep-choice':run(()=>G.choice(state,cid,b.dataset.value));break;
 case 'finish-operations':run(()=>G.finishOperations(state));break;case 'finish-upkeep':run(()=>G.finishUpkeep(state));break;case 'pay-arrears':{const total=state.arrears.reduce((n,a)=>n+a.amount,0),wages=state.jobs.filter(j=>!j.settled).reduce((n,j)=>n+j.quote.pay,0),reserve=G.forecast(state)+wages,spare=Math.min(total,Math.max(0,state.cash-reserve));show('Pay part of the arrears',`<p>Routine administration: no Guild Action. Pay a chosen amount instead of emptying the treasury. Existing creditor balances remain owed.</p><div class="quote-box">Cash ${state.cash}; arrears ${total}. Suggested reserve: ${reserve} (${G.forecast(state)} next Upkeep + ${wages} committed mission wages). Payment retaining that reserve: ${spare}. Future client receipts are not guaranteed.</div><div class="form-row"><label for="arrears-budget">Payment budget</label><input id="arrears-budget" type="number" min="1" max="${Math.min(total,state.cash)}" value="${spare}"></div><p>You may deliberately pay more than the suggestion. A zero suggestion means there is no reserve-safe payment currently.</p>${dialogActions('Pay this amount','pay-arrears-confirm')}`);break;} case 'pay-arrears-confirm':if(run(()=>G.payArrears(state,Number($('arrears-budget').value))))close();break;
 case 'reset-confirm':{const seed=Number($('seed').value),free=$('acquisition').value==='free';if(!Number.isInteger(seed)||seed<0||seed>999999){$('modal-error').textContent='Choose an integer seed from0 to999999.';break;}const partySize=Number($('party-size').value);if(!Number.isInteger(partySize)||partySize<1||partySize>8){$('modal-error').textContent='Choose 1–8 PC party members.';break;}state=G.fresh(seed,free,partySize,$('preset').value);activeOfficer='command';tab='development';close();save();render();notify('Fresh playtest started. Seed '+seed+' · '+(free?'free':'paid')+' contract acquisition.');break;}
}});
document.addEventListener('input',e=>{if(e.target.id==='loan-amount')updateLoanQuote();});
document.addEventListener('change',e=>{if(e.target.id==='loan-collateral')updateLoanQuote();if(e.target.id==='operating-base'){if(run(()=>G.focusBase(state,e.target.value))){activeOfficer=state.officers.find(o=>o.baseId===state.operatingBase)?.id||'command';render();}}if(e.target.id==='active-officer'){activeOfficer=e.target.value;render();}if(e.target.matches('#modal input[name="crew"]')){if(dialogData?.cid)updateDeployment(true);else updatePersonnel();}if(e.target.matches('#modal select[data-lead],#squad-leader'))updateDeployment(false);});
$('feedback').addEventListener('input',e=>{state.feedback=e.target.value;save();});$('close-modal').addEventListener('click',close);$('modal').addEventListener('close',()=>{modalType=null;dialogData=null;});
window.GuildPlaytest={getState:()=>JSON.parse(JSON.stringify(state)),render};render();
})();
